#!/usr/bin/env bash
# ==============================================================================
# Script: 05-join-worker.sh
# Purpose: Join a worker node to the Kubernetes cluster using kubeadm join.
# Target: Run on WORKER nodes
# Usage:
#   sudo ./05-join-worker.sh <CONTROL_PLANE_IP:6443> <TOKEN> <CA_CERT_HASH>
# Or execute the join script generated by 03-init-control-plane.sh directly:
#   sudo /tmp/kubeadm-join.sh
# ==============================================================================

set -euo pipefail

if [ "$#" -eq 3 ]; then
  CONTROL_PLANE_ADDR="$1"
  JOIN_TOKEN="$2"
  CA_HASH="$3"

  echo "=========================================================="
  echo ">>> Joining cluster at ${CONTROL_PLANE_ADDR}..."
  echo "=========================================================="
  sudo kubeadm join "${CONTROL_PLANE_ADDR}" \
    --token "${JOIN_TOKEN}" \
    --discovery-token-ca-cert-hash "${CA_HASH}" \
    --cri-socket="unix:///run/containerd/containerd.sock"

elif [ -f "/tmp/kubeadm-join.sh" ]; then
  echo ">>> Found /tmp/kubeadm-join.sh. Executing..."
  sudo bash /tmp/kubeadm-join.sh
else
  echo "Usage: sudo $0 <CONTROL_PLANE_IP:6443> <TOKEN> <CA_CERT_HASH>"
  echo "Example:"
  echo "  sudo $0 192.168.56.10:6443 abcdef.0123456789abcdef sha256:1a2b3c4d..."
  echo ""
  echo "Tip: Run the following on the Control Plane node to get a fresh join command:"
  echo "  kubeadm token create --print-join-command"
  exit 1
fi

echo "=========================================================="
echo ">>> [SUCCESS] Worker node joined the cluster successfully!"
echo ">>> Verify on the Control Plane with: kubectl get nodes"
echo "=========================================================="
